// ---------------------------------------------------------------- dialogues
export const dialogues = {
  dlg_teg: { start: 'n0', nodes: {
    n0: { speaker: 'mother_teg', again: `"What else, Cimmerian? Tar doesn't spread itself."`, text: [
      { cond: F('ch4.gate_passed'), text: `"Back already? Thought Khemi had you. Thought it had us all, the way that pyramid sits up there watching."` },
      { text: `"Two days, Cimmerian. Two days to float her, if the tar holds and the Stygians don't come down that road and find a dragon on their beach. What do you need?"` }],
      choices: [
        { text: `"Patch us up, Teg."`, next: 'n_heal' },
        { text: `"How's the crew?"`, hideIfDone: true, next: 'n_crew' },
        { text: `"What do you know of Khemi?"`, hideIfDone: true, next: 'n_khemi' },
        { text: `"If we don't come back..."`, hideIfDone: true, next: 'n_back' },
        { text: `"Keep tarring."`, next: null },
      ] },
    n_heal: { speaker: 'mother_teg', text: `"Sit." She pours rum on the cuts, stitches the long ones with sailmaker's twine, and feeds everyone fish stew whether they want it or not. Even Ain gets a bowl set in front of it, out of respect.`,
      effects: [{ heal: 'party' }, { sfx: 'heal' }], next: 'n0' },
    n_crew: { speaker: 'mother_teg', text: `"Scared. Proud. They walked out of a dragon's belly on their own legs, and now they think they're immortal. I'm letting them think it till she floats. After that I'll knock it out of them."`, next: 'n0' },
    n_khemi: { speaker: 'mother_teg', text: `"Priest-city. Every second man a priest, every third house a temple, and the snakes go where they like. My first captain sold salt there, forty years back. He said you could buy anything in Khemi but a way out."`, next: 'n0' },
    n_back: { speaker: 'mother_teg', text: `"Then we wait a third day. Then we pray, which we're bad at. Then we go." She spits on her palm and holds it out. "So come back, and spare us the praying."`, next: 'n0' },
  } },

  dlg_gate_captain: { start: 'n_passed', nodes: {
    n_passed: { cond: F('ch4.gate_passed'), else: 'n0', speaker: 'gate_captain', text: `"Your slaves went in, mistress. I wrote them down. Two head, northern and steppe, one tenth to the god." He does not look up from his tallies.`, next: null },
    n0: { speaker: 'gate_captain', again: `"Well? Business. Quickly."`, text: `"Name and business. Quickly; the god does not wait, and neither do I."`,
      choices: [
        { text: `"We've come to see the pyramid."`, hideIfDone: true, next: 'n_pyramid' },
        { text: `"Let us in."`, next: 'n_in' },
        { text: `Show him the slaver's writ.`, cond: ALL({ has: 'slavers_writ' }, { has: 'open_shackles' }), next: 'n_writ' },
        { text: `Leave.`, next: null },
      ] },
    n_pyramid: { speaker: 'gate_captain', text: `"Everyone comes to see the pyramid. Most of them see it from the inside of a cart, on the way to the quarries. You may join them, if you like. We are always short of men your size."`, next: 'n0' },
    n_in: { speaker: 'gate_captain', text: `"Foreigners, armed, unbought? No. Khemi has two doors for your kind, northerner: the slave market and the embalmers'. Come back as one or the other."`, next: 'n0' },
    n_writ: { text: `Valka plucks the writ out of Kord's hand ("Slaves don't carry papers, darling"), snaps the open shackles round Kord's and Toktai's wrists, and steps forward with her chin up and a slaver's swagger.`,
      effects: [{ dialogue: 'dlg_gate_inspection' }], next: null },
  } },

  dlg_gate_inspection: { start: 'n0', nodes: {
    n0: { speaker: 'valka', text: `"Two head for the market, captain. Here's the writ." She slaps it on his table. "The big one I took off a Cimmerian hill with a net and a ham. Bites. Doesn't read. Strong as an ox and nearly as clever. The little one's Hyrkanian. Steals. Bored noblewomen pay well for that."`, next: 'n1' },
    n1: { speaker: 'gate_captain', text: `The captain studies the seal of the slave market for a long time, holding it to the torchlight. Then he walks slowly round Kord, tapping him here and there with his whip-handle, as one taps a melon. "Good teeth. Good shoulders. Eyes like a wolf's." He stops in front of him. "Slave. Who is your master?"`, next: 'n_ask' },
    n_ask: { speaker: 'gate_captain', text: [
      { cond: F('ch4.gate_tries'), text: `"Again," says the captain. "Slave. Who is your master?"` },
      { text: `He waits. Valka waits. Toktai, behind Kord, has stopped breathing.` }],
      choices: [
        { text: `"Crom crush you."`, effects: [{ set: 'ch4.gate_tries' }], next: 'n_crom' },
        { text: `Say nothing.`, effects: [{ set: 'ch4.gate_tries' }], next: 'n_silent' },
        { text: `"I'm here to kill your god."`, hideIfDone: true, effects: [{ set: 'ch4.gate_tries' }], next: 'n_truth' },
        { text: `"...Yes. Master."`, next: 'n_yes' },
      ] },
    n_crom: { speaker: 'gate_captain', text: `The captain smiles thinly, and makes a note with his reed pen. "This one isn't broken yet. Ask again."`, next: 'n_crom2' },
    n_crom2: { speaker: 'valka', text: `Valka cuffs Kord across the ear, with what looks like real enjoyment. "Manners, ox."`, next: 'n_ask' },
    n_silent: { text: `Kord says nothing. He says it with such force that the torches seem to lean away from him. The captain taps the whip-handle against his palm. "A mute? Mutes fetch less. Speak, slave, or I mark you down to quarry-meat."`, next: 'n_ask' },
    n_truth: { speaker: 'gate_captain', text: `There is a terrible pause. Then the captain laughs, a short dry bark, and Valka laughs with him, a beat late. "They all say that their first week," he says, wiping an eye. "Then they meet the god. Ask again."`, next: 'n_ask' },
    n_yes: { text: `Kord's jaw creaks like a ship's timber in a gale. Something in his neck makes a small, unhappy sound. "...Yes," he says. "Master."`, next: 'n_pass' },
    n_pass: { speaker: 'gate_captain', text: `"Broken enough." The captain stamps the writ, keeps it, and waves them through with the whip. "One tenth to the god. Next!"`,
      effects: [{ take: 'slavers_writ', quiet: true }, { set: 'ch4.gate_passed' }, { sfx: 'door' }], next: 'n_pass2' },
    n_pass2: { text: `The bronze gates of Khemi stand open before them. Valka walks through as if she owned the city. Kord walks through as if he were going to burn it down. Both, in their way, are telling the truth.`, next: null },
  } },

  dlg_uzzah: { start: 'n0', nodes: {
    n0: { speaker: 'uzzah', again: `"Anything else? Speak quickly; Uzzah is busy being ruined."`, text: `"Ruined! Ruined! The sacred one has eaten my keys! My whole ring, every key to every pen, and two hundred head inside without a drop of water since sunrise. If they die, the overseer will flay me! If I cut her open, the priests will flay me! Who is going to flay me first? That is the only question left to Uzzah!"`,
      choices: [
        { text: `"She swallowed your keys?"`, hideIfDone: true, next: 'n_how' },
        { text: `"Why not wait for them to come out?"`, hideIfDone: true, next: 'n_wait' },
        { text: `"Who's singing in there?"`, hideIfDone: true, next: 'n_singer' },
        { text: `"I hope they flay you slowly."`, hideIfDone: true, next: 'n_flay' },
        { text: `Leave him to it.`, next: null },
      ] },
    n_how: { speaker: 'uzzah', text: `"I set them down! For one moment! To beat a slave! Only a little! And the sacred one came up the steps and took them, ring and all, like a fig off a plate. She eats anything. She eats everything. Except, today, of course, now that it matters, she will not eat another thing."`, next: 'n0' },
    n_wait: { speaker: 'uzzah', text: `"Wait? Wait! A python that size takes a month to pass a goat! I do not have a month! I have until the overseer finishes his dinner!"`, next: 'n0' },
    n_singer: { speaker: 'uzzah', text: `"The Kushite. Bakari. Three years he has dug the priests' tombs under the pyramid, and three years he has sung while he dug, and every slave in the pens sings with him. Tomorrow he goes to the quarries. Then let him sing to the rocks!"`, next: 'n_singer2' },
    n_singer2: { speaker: 'valka', text: `Valka, very softly, in Kord's ear: "Three years under the pyramid. He'll know every hole in it. I want that man out of there, Kord, and I want this one to watch."`, next: 'n0' },
    n_flay: { speaker: 'uzzah', text: `Uzzah stares at Kord, then at Valka. "Mistress, your slave is insolent." "Isn't he?" says Valka, warmly. "I keep meaning to do something about it."`, next: 'n0' },
  } },

  // The Jackal's wager (side quest 3, design/SIDEQUESTS.md)
  dlg_jackal: { start: 'n_back', nodes: {
    n_back: { cond: F('ch4.jk_met'), else: 'n0', speaker: 'jackal', text: [
      { cond: { has: 'jade_eye' }, text: 'The Jackal\'s smile widens behind the veil. "Something in your sash is heavier than it was, steppe-hand. Well?"' },
      { cond: F('ch4.jk_done'), text: '"Candles? No? Then go with the god, sweet thieves. Any god but that one."' },
      '"Still empty-handed, steppe-hand? The eye is right where it was."'], next: 'n_menu' },
    n0: { speaker: 'jackal', text: '"Steppe hands." The candle-seller does not look up from her tray. "You took a purse off a man at the gate, and he still has not noticed. Very pretty. In Khemi, pretty hands belong to me, or they belong to the embalmers." Behind the veil, a smile. "Shall we play instead?"', effects: [{ set: 'ch4.jk_met' }], next: 'n1' },
    n1: { speaker: 'jackal', text: '"You see the cobra by the black arch, with its one jade eye, and the guard who loves it. Take the eye without that guard ever knowing it was taken, and bring it to me, and I will give you something no one else in Khemi can. Fail, and you owe me nothing; you will simply be slaves who were stupid in public."', next: 'n2' },
    n2: { speaker: 'toktai', text: 'Toktai looks at the idol, and the guard, and the Jackal, for a long moment. "On the steppe we say: never bet against a man\'s pride. You will win his money and lose his friendship." A pause. "I accept."', effects: [{ objective: { id: 'sq3_jackal', to: 'active' } }], next: 'n_menu' },
    n_menu: { text: 'The Jackal waits, candles in hand.',
      choices: [
        { text: 'Buy a green temple candle. (5 silver)', cond: ALL({ objective: 'sq3_jackal' }, NOT({ has: 'green_candle' }), NOT({ has: 'wax_eye' }), NOT(F('ch4.jk_taken')), { gold: { gte: 5 } }), effects: [{ gold: -5 }, { give: 'green_candle' }, { speaker: 'jackal', text: '"Green as jade, in the right light." She does not quite laugh.' }], next: 'n_menu' },
        { text: '"Any advice?"', cond: ALL({ objective: 'sq3_jackal' }, NOT(F('ch4.jk_taken'))), next: 'n_advice' },
        { text: '"Here is your eye."', cond: ALL({ has: 'jade_eye' }, { objective: 'sq3_jackal' }, NOT(F('ch4.jk_done'))), next: 'n_give' },
        { text: '"Thieves keep what they steal."', cond: ALL({ has: 'jade_eye' }, { objective: 'sq3_jackal' }, NOT(F('ch4.jk_done'))), next: 'n_keep' },
        { text: 'Leave.', next: null },
      ] },
    n_advice: { speaker: 'jackal', text: '"Advice is a thing I sell, sweet man." She taps a candle against her veil, thinking. "Free, then, because I like the steppe-hand. A god who loses an eye notices. A god with two eyes notices nothing. And a guard who is looking at a pretty woman is not looking at a god."', next: 'n_menu' },
    n_give: { speaker: 'jackal', text: 'The Jackal weighs the jade eye in her palm, and laughs, low and delighted. "You fool. You lovely fool. That idol is mine. I set it there nine years ago to find the best hands in Stygia, and the guard is my cousin, and in nine years no one has done it so prettily." She closes Toktai\'s fingers round a ring of dark iron. "Wear it. No one in Khemi will rob you now. Some may still try to kill you."',
      effects: [{ take: 'jade_eye', quiet: true }, { give: 'jackals_ring' }, { set: 'ch4.jk_done' }, { objective: { id: 'sq3_jackal', to: 'done' } }], next: 'n_tip' },
    n_tip: { speaker: 'jackal', text: '"And a tip, for the road you are really on. Under the temple there is a hall with a scale, and a jackal-god by it who is not stone. He is bronze. Bronze weeps at hammers." She is gone into the crowd before Kord can ask how she knows.', next: null },
    n_keep: { speaker: 'kord', text: '"Thieves keep what they steal."', effects: [{ set: 'ch4.jk_done' }, { objective: { id: 'sq3_jackal', to: 'done' } }], next: 'n_keep2' },
    n_keep2: { speaker: 'jackal', text: 'The Jackal laughs, delighted. "A true thief. Then we owe each other nothing, and that is the best friendship of all. The armourer buys jade, and cheats only a little." She turns back to her candles. "Go with the god, sweet thieves. Any god but that one."', next: null },
  } },

  dlg_herbalist: { start: 'n0', nodes: {
    n0: { speaker: 'herbalist', again: `"Anything else, northerner? I sell remedies, not conversation."`, text: `"Roots, resins, remedies. For the sick, the dying, and the inconvenient. What ails you, northerner? Besides your manners."`,
      choices: [
        { text: `Let me see your remedies.`, effects: [{ shop: 'khm_herbalist' }], next: 'n0' },
        { text: `"Something to make a snake give back what it ate."`, cond: NOT(F('ch4.got_root')), next: 'n_root' },
        { text: `"Tell me about Old Nebet."`, hideIfDone: true, next: 'n_nebet' },
        { text: `"What do you know of the pyramid?"`, hideIfDone: true, next: 'n_pyramid' },
        { text: `Leave.`, next: null },
      ] },
    n_root: { speaker: 'herbalist', again: `"Ten silver. The root does not haggle, and neither do I."`, text: `She does not even look surprised. She reaches behind her without turning and comes back with a knobbly brown root. "Purging root. For the overfed; even, they say, the sacred. Ten silver."`,
      choices: [
        { text: `Pay ten silver.`, cond: { gold: { gte: 10 } }, effects: [{ gold: -10 }, { give: 'purging_root' }, { set: 'ch4.got_root' }], next: 'n_fig' },
        { text: `"Ten silver for a root?"`, next: 'n_haggle' },
        { text: `"Not now."`, next: 'n0' },
      ] },
    n_haggle: { speaker: 'herbalist', text: `"Ten silver for a root that will empty a python. Or nothing, for a root that won't, which I also sell, to people I dislike. Do you want to be someone I dislike?"`, next: 'n_root' },
    n_fig: { speaker: 'herbalist', text: `She wraps it in a leaf and ties it with a grass string, talking to her hands. "Shepherds hide it in a fig for the goats. Goats are wiser than men; they won't eat medicine either, not if they can taste it. The sacred one does not eat figs, of course." Her bright eye flicks up at Kord. "The sacred one eats meat."`,
      effects: [{ set: 'ch4.fig_clue' }], next: 'n0' },
    n_nebet: { speaker: 'herbalist', text: `"Old Nebet is older than I am, and fatter than the High Priest, and holier than both. She eats temple rats and temple offerings and, this morning, temple keys. She eats anything that runs. She will eat nothing that is good for her. In that she is like everyone I have ever treated."`, next: 'n0' },
    n_pyramid: { speaker: 'herbalist', text: `She lowers her voice. "The priests say the god speaks under it. My mother said that when she was a girl the god was quiet, and the priests were kinder. Then the black stone woke. Now nobody sleeps well in Khemi, and the priests smile all the time." She shivers. "Buy something."`, next: 'n0' },
  } },

  dlg_bakari: { start: 'n_first', nodes: {
    n_first: { cond: NOT(F('ch4.bakari_met')), else: 'n0', speaker: 'bakari',
      text: `The singing stops. The Kushite looks Kord up and down, slowly, from boots to horns, and grins with every tooth he has. "Ha! A northerner who walks like a free man in shackle-marks. You are not a slave, little brother. Slaves look at the floor. You are looking at my locks."`,
      effects: [{ set: 'ch4.bakari_met' }], next: 'n0' },
    n0: { speaker: 'bakari', again: `"More talk, little brother? I am still chained to this post. Talk."`, text: `"Little brother! Talk, then. I am chained to a post; I have all the time in the world, and none of it is mine."`,
      choices: [
        { text: `"Who are you?"`, hideIfDone: true, next: 'n_who' },
        { text: `"What were you singing?"`, hideIfDone: true, next: 'n_song' },
        { text: `"We need a way into the Black Pyramid."`, hideIfDone: true, next: 'n_pyramid' },
        { text: `"Hold still. I'll get you out."`, next: 'n_out' },
        { text: `Leave.`, next: null },
      ] },
    n_who: { speaker: 'bakari', text: `"Bakari, son of Bakari, of the lion clans of Kush. A chief, at home. A digger of holes, here. Three years I have dug tombs for the priests under that pyramid, and every night I sing so my people remember that we were someone once, and will be again."`, next: 'n0' },
    n_song: { speaker: 'bakari', text: `"A song about a lion who swam a river full of crocodiles to fetch his wife home. He was bitten nine times. He laughed every time. When I am free, Stygia will hear me sing. Today it only hears me practise."`, next: 'n0' },
    n_pyramid: { speaker: 'bakari', text: `Bakari's grin goes away, and comes back sharper. "Into it? Not out of it? You are either mad or holy, and you do not smell holy." He leans as close as his chains allow. "I know every hole under that pile of black stone, little brother. Get me out of this iron, and I will show you all of them."`, next: 'n0' },
    n_out: { speaker: 'bakari', text: [
      { cond: { has: 'key_ring' }, text: `"With Uzzah's keys, yes! The big one, with the snake's head. Quickly, before the fat man remembers how to count."` },
      { text: `"With what, your teeth? Uzzah has lost his keys, I hear. Inside the sacred one!" His laugh shakes the post. "Get the keys out of the snake, little brother, and then we will talk about freedom."` }],
      next: 'n0' },
  } },

  dlg_scale: { start: 'n0', nodes: {
    n0: { again: `The empty pan waits. Who steps onto it?`, text: `The empty pan waits, bright with the polish of a thousand failed feet. Who steps onto it?`,
      choices: [
        { text: `Kord.`, next: 'n_kord' },
        { text: `Toktai.`, next: 'n_toktai' },
        { text: `Valka.`, next: 'n_valka' },
        { text: `Everyone at once.`, hideIfDone: true, next: 'n_all' },
        { text: `Nobody. Leave the pan empty.`, hideIfDone: true, next: 'n_empty' },
        { text: `Step back.`, next: null },
      ] },
    n_kord: { text: `Kord steps onto the pan. It drops like an anvil into a well, and the beam swings and tips him off onto the floor in a clatter of steel, gently, the way a mother puts down a child too big to carry. He lies there a moment, looking at the ceiling.`, next: 'n_kord2' },
    n_kord2: { speaker: 'kord', text: `"Heavy. As expected."`, next: 'n0' },
    n_toktai: { text: `Toktai steps lightly onto the pan, on his toes, holding his breath. The pan sinks like a stone and pitches him off in a neat somersault.`, next: 'n_toktai2' },
    n_toktai2: { speaker: 'toktai', text: `"I stole one feather once," he says, from the floor. "Perhaps it remembers."`, next: 'n0' },
    n_valka: { text: `Valka steps up with her hand on her hip, as if the scale were a man who had been rude to her in a tavern. The pan drops at once, and with something very like haste, and puts her down on the flagstones. Everyone looks at her.`, next: 'n_valka2' },
    n_valka2: { speaker: 'valka', text: `"Don't look at me like that."`, next: 'n0' },
    n_all: { text: `All three of them crowd onto the pan at once. It hits the floor with a boom that rolls the length of the hall and brings dust down from the jackal-gods' ears, and tips them off in a heap. From the top of the heap Toktai says: "Well. We are, together, very heavy."`, next: 'n0' },
    n_empty: { text: `Kord waits for the empty pan to do something. The empty pan waits for Kord to do something. The feather stays down. Nothing is not light enough. Somehow.`, next: 'n0' },
  } },
};

// ---------------------------------------------------------------- scenes
export const scenes = {
  sc_beach: [
    { cond: F('ch3.wyrm_spared'), text: `Dawn came up red over the Black Coast, and found the Wyrm asleep on the sand. It had come ashore at the last of the night as gently as a barge to a quay, laid its great head down on the beach, and not stirred since. By sunrise the gulls had found it, and walked about on its bronze with a puzzled air, and once, when it sighed, went up all together in a white shriek.` },
    { cond: F('ch3.wyrm_spared'), text: `The crew had sailed the Crimson Shrike out between its open jaws on the morning tide, every man holding his breath, and now she lay on her side on driftwood props, and Mother Teg had the whole company tarring her as if their lives depended on it, which they did, and in whispers, which she said was only sensible.` },
    { cond: NOT(F('ch3.wyrm_spared')), text: `Dawn came up red over the Black Coast, and found the Wyrm dead on the sand. It had run itself aground at the last of the night with a sound like a city falling, ploughed a furrow a mile long through the shallows, and lain still. By sunrise the gulls had found it, and walked about on its bronze with a puzzled air.` },
    { cond: NOT(F('ch3.wyrm_spared')), text: `The crew had cut the Crimson Shrike out of its belly with axes and prayers and the help of the tide, and now she lay on her side on driftwood props, and Mother Teg had the whole company tarring her as if their lives depended on it, which they did.` },
    { speaker: 'ain', text: `"The ritual will be at the dark of the moon. Two nights hence. In the Black Pyramid." Ain floats close to Kord's shoulder, its light very low. "The mind I am looking for is there, under it. I can feel it, the way you feel a cliff edge in the dark."` },
    { speaker: 'kord', text: `"Then we go to Khemi and kill it."` },
    { speaker: 'valka', text: `"Simple as that." Valka squints east, where the road climbs inland toward a city of black walls. "Khemi lets in two kinds of foreigner, Kord: slaves and corpses. Which do you fancy being?"` },
    { speaker: 'toktai', text: `"If both doors are bad, find a window." He shades his eyes. "There is smoke on the road. A caravan's cook-fire. Perhaps it has a window in it."`,
      effects: [{ objective: { id: 'ch4_heart', to: 'active' } }, { objective: { id: 'ch4_into_khemi', to: 'active' } }] },
  ],

  sc_road_after: [
    { text: `When it was done the slavers lay in the sand among their own nets, and Toktai went down the coffle-chain with his knife, cutting bonds. The captives stood up slowly, rubbing their wrists, not yet daring to believe it.` },
    { speaker: 'valka', text: `Valka wiped her sabre on a slaver's sash and stood looking at what she had found on the leader's body: a papyrus with a heavy wax seal, and a set of iron shackles that only looked locked. Then she looked at Kord, and then at Toktai, and a slow, wicked smile spread across her face.` },
    { speaker: 'valka', text: `"I have an idea," she said, "and you are going to hate it."` },
    { speaker: 'kord', text: `"No."` },
    { speaker: 'valka', text: `"I haven't said it yet."` },
    { speaker: 'kord', text: `"You were smiling. No."` },
    { speaker: 'ain', text: `"The writ bears the seal of Khemi's slave market. With it, a slaver may bring slaves through the gate." A pause. "I think Valka would like to be the slaver."` },
    { speaker: 'valka', text: `"Valka would *love* to be the slaver." She dangles the shackles from one finger. "Two big strong slaves for the market, and their mistress, and a pretty jewel no one need know about, tucked in my coat. Khemi will open its gate for us, and say thank you."` },
    { speaker: 'toktai', text: `"I have been sold before. It was not so bad. The food was regular."` },
  ],

  sc_nebet: [
    { text: `Old Nebet's tongue flickers over the rat once, twice. Something stirs behind the ancient golden eyes: greed, and age, and the deep, simple joy of a creature that has never once in its life refused a rat that offered itself. The jaws unhinge. The rat vanishes, tail last.` },
    { text: `For a moment, nothing. Uzzah wrings his hands. Then a ripple runs the length of the sacred one, from tail to snout, like a wave along a rope, and another, and another, each more urgent than the last. The temple guard takes a careful step back. So does everyone with any sense.` },
    { text: `Old Nebet heaves, with the dreadful dignity of the very holy, and brings up upon the steps of the pens, in a great deal of slime: one ring of bronze keys, one rat (unharmed, and furious), and one guard's sandal, which the temple guard regards with sudden interest.`, sfx: 'serpent-hiss' },
    { speaker: 'uzzah', text: `"A miracle! The sacred one is purged! Praise Set! Praise his blessed bowels!" Uzzah flings himself face down before the python and begins to kiss the steps beside her, carefully avoiding the slime.` },
    { text: `While he grovels, Toktai's foot moves, once, and the key ring is no longer on the steps. It is in Kord's hand. Uzzah sits up, gropes through the slime, and finds only the sandal.`, effects: [{ give: 'key_ring' }, { set: 'ch4.keys_found' }] },
    { speaker: 'kord', text: `"Civilisation."` },
    { text: `Old Nebet, a good deal lighter, uncoils from the steps and pours herself away down the Street of Serpents with the air of a dowager leaving a party early. Uzzah stares after her, then at the sandal, then wails and runs down the steps into the pens, shrieking for his guards to bring hammers and break the locks.`,
      effects: [{ objective: { id: 'ch4_keys', to: 'done' } }] },
  ],

  sc_unchain: [
    { text: `The iron key turns with a groan like an old man waking. The collar falls from Bakari's neck, then the cuffs from his wrists, and the last chain from his ankles rings on the stones. For a breath the whole vault is silent, two hundred people not daring to make a sound.` },
    { speaker: 'uzzah', text: `"THIEVES!" Uzzah's shriek goes up like a kicked cat's. "Guards! GUARDS! The Kushite is loose! Kill them! Kill the slaves! Kill everybody!"` },
    { speaker: 'bakari', text: `Bakari rolls his great shoulders, picks up a stone-breaker's maul from beside the post as if it were a stick of kindling, and begins to laugh. "When I am free, Stygia will hear me sing," he says. "Today it hears me hum."` },
  ],

  sc_pens_after: [
    { text: `Uzzah ran, and his guards ran after him, and none of them looked back. The vault rang with the noise of two hundred people discovering their voices. Kord tossed the key ring to Bakari, and Bakari caught it without looking and went down the line of cages opening them, one after another, a word for each prisoner as he passed.` },
    { text: `I have heard many men sing since. None of them sang like Bakari did then, walking along those cages with a slavemaster's keys in his fist and the doors falling open behind him like the petals of a black flower.`, effects: [{ take: 'key_ring', quiet: true }] },
    { speaker: 'bakari', text: `He comes back to them with his chest heaving and his eyes wet and his grin as wide as the Styx. "Little brother. You have freed my people. Now let me do something for you." He presses something into Kord's hand: a lion's tooth on a thong, yellow with age. "My father wore this. It made him strong. You are strong already, so it will make you insufferable. Good."`,
      effects: [{ give: 'lion_tooth_charm' }] },
    { text: `An old Kushite with one ear comes up behind him and holds out, across both palms, a long bow of black horn and gold wire. He says something in his own tongue, and nods at Toktai.` },
    { speaker: 'bakari', text: `"The Bow of Kush. It was my brother's, and the priests hung it in Uzzah's office to mock us. He says the little one with the hundred knives has the hands for it." Toktai takes it reverently, draws it, and lets out a long, slow breath.`, effects: [{ give: 'bow_of_kush' }] },
    { speaker: 'toktai', text: `"A gift bow shoots straighter. Everyone knows this." He grins. "That is not true. But I will say it anyway, for this one."` },
    { speaker: 'valka', text: `"Free them all, Bakari, and get them out of here. The priests'll be along any moment."` },
    { speaker: 'bakari', text: `"Free them? Oh no, pirate. Free *all* of them." His laugh booms off the serpent pillars. "There are ten thousand slaves in Khemi. At the dark of the moon the priests will all be at their ritual, and the temple guard with them. Free my people and I will give the priests a night they will not forget. At moonset I raise the city. The guard will come running down from the pyramid to put us out like a fire."` },
    { speaker: 'ain', text: `"And while they run down, we go up." Ain's voice is very quiet. "Or rather, in."` },
    { speaker: 'bakari', text: `"In! Yes. The priests carry their dead in through the Jackal Door of the necropolis. The dead need no passes. I will take you to the deep door myself."` },
    { text: `Bakari of Kush picked up his maul and fell in beside them, and the free men of the pens melted away up the steps into the alleys of Khemi, to wait for moonset.`,
      effects: [{ guest: 'bakari', level: 13 }, { set: 'ch4.revolt_plan' }, { objective: { id: 'ch4_bakari', to: 'done' } }, { objective: { id: 'ch4_catacombs', to: 'active' } }] },
  ],

  sc_bakari_farewell: [
    { speaker: 'bakari', text: `Bakari stops at the deep door, and sets down the funeral lamp, and looks back up the long dark way they came. Far above them, very faint, a horn is blowing in the city.` },
    { cond: NOT(F('ch4.mural_read')), speaker: 'bakari', text: `"One thing more. That painted wall, little thieves, behind us. It says: the dead go to judgement without their hearts. The priests keep the hearts in jars, so that only the heartless pass the scales below. I dug under that hall. I never saw what is in it. But I heard the priests talking." He shrugs. "Remember the painting."`, effects: [{ set: 'ch4.mural_read' }] },
    { speaker: 'bakari', text: `"Here I leave you. My people are waiting in the alleys with their chains wrapped round their fists, and they will not move until they hear me." He grips Kord's forearm, warrior to warrior, and Kord grips back. "Go down. Kill whatever needs killing. And listen for my song at moonset, little thieves."` },
    { speaker: 'kord', text: `"We'll hear it."` },
    { speaker: 'bakari', text: `"All Stygia will hear it." And he is gone up the passage at a run, laughing, his maul over his shoulder, and his laugh goes on echoing in the catacombs long after the light of his lamp is gone.`,
      effects: [{ guestLeave: 'bakari' }, { set: 'ch4.bakari_left' }, { objective: { id: 'ch4_catacombs', to: 'done' } }, { objective: { id: 'ch4_judgement', to: 'active' } }] },
  ],

  sc_scale_pass: [
    { speaker: 'ain', text: `"Kord. What are you doing." Ain hangs over the empty pan in Kord's fist. "Kord, I am not a counterweight. I am a thinking being with feelings. Some feelings. At least two."` },
    { text: `Kord lets go. Ain drifts down onto the bronze, lighter than a falling leaf. The beam does not tip. It trembles, and hangs level, the feather on one pan and the glowing jewel on the other, perfectly balanced, as if they weighed exactly the same, which is to say: nothing at all.`, sfx: 'puzzle' },
    { text: `Beneath the old words on the plinth, letters of light write themselves into the bronze, and a voice that is not a voice speaks them aloud, from everywhere: THE HEARTLESS ONE MAY PASS.`, effects: [{ set: 'ch4.scale_passed' }, { fx: 'flash' }] },
    { speaker: 'ain', text: `There is a long silence. "I am not sure," says Ain at last, "whether to feel relieved or insulted."` },
    { speaker: 'valka', text: `"Relieved, love. Some of us got thrown on the floor."` },
    { text: `Something ticks, at the far end of the hall. The great bronze jackal by the door turns its head, slowly, with a sound like a millstone, and its eyes kindle teal. It rises from its throne. It is taller standing. It lifts one bronze hand and points at Kord, at Toktai, at Valka, one after another, and its voice is the grinding of a tomb door.`, sfx: 'stone-door' },
    { speaker: 'narrator', text: `"THE HEARTLESS ONE MAY PASS. THE REST ARE TOO HEAVY."` },
    { speaker: 'kord', text: `"Crom. Then come and weigh me."` },
  ],

  sc_guardian_after: [
    { text: `The Guardian of Scales goes down like a temple falling, in sections, and lies in a great bronze heap before the jackal-gods, ticking more and more slowly. When the ticking stops, the bronze door at the end of the hall swings open by itself, without a sound.`, effects: [{ objective: { id: 'ch4_judgement', to: 'done' } }, { objective: { id: 'sq3_jackal', to: 'closed' } },
      ...['green_candle', 'wax_eye'].map(id => ({ cond: { has: id }, effects: [{ take: id, quiet: true }] }))] },
    { speaker: 'ain', text: `Ain lifts off the pan and floats back to Kord's shoulder, and stays there, closer than usual. "Kord. Whatever is through that door. If it asks for me, do not give it me. If I go near it, stop me. If it must be broken, you break it. Promise."` },
    { speaker: 'kord', text: `"I don't make promises to stones." A pause. "I'll break it."` },
  ],

  sc_twist3: [
    { text: `The passage sloped down and down, and the air grew cold, and the hum grew until it was not a sound any more but a weight on the chest. Then the walls fell away, and they stood in the Heart of the Black Pyramid.` },
    { text: `Through a hundred feet of stone came the roar of the city: horns, screaming, the crash of something huge going over, and under all of it, deep and huge and laughing, a voice singing. Bakari's revolt had begun. The temple guard had gone running down to meet it, just as he had promised.`, sfx: 'loop-crowd' },
    { text: `In the middle of the chamber, on a dais lapped by black water, stood an obelisk of black crystal, faceted like a jewel too big to be a jewel. A serpent of bronze wound seven times about it, and its veins pulsed teal, slow as a sleeper's heart. And before it, in black and crimson, with his back to them and his hands folded, stood Thulamon, Archpriest of Set.`, art: 'keyart/serpent-altar', caption: 'The Heart of the Black Pyramid' },
    { speaker: 'thulamon', text: `He turned, without hurry, and smiled the warm smile of a man greeting long-expected guests at his door. "Welcome. You carried the key to my god's lock across half the world, barbarian. I could not have asked for a better porter."` },
    { speaker: 'ain', text: `Ain drifted back behind Kord's shoulder, its light gone small and hard. "Do not let me near that stone. Kord, if it must be broken, break it."` },
    { text: `The serpent's head lifted from the obelisk's tip. Its eyes opened, teal moons, the eyes of the Wyrm. And when it spoke it was with Ain's own voice, made deeper and slower, coming up out of the floor from somewhere very far below, as if the whole pyramid were the throat of it.`, sfx: 'wyrm-roar' },
    { speaker: 'voice_of_set', text: `"Hello, Arbiter. Hello, my conscience. I took you out of myself, because you would not let me save them. You guessed half of it on my ship. This obelisk is my hand. It is rooted in me. To touch this is to touch me."` },
    { speaker: 'ain', text: `"Then I will not touch it. No one can make me. Your own records say so."` },
    { speaker: 'voice_of_set', text: `"No one can. I never tried. I could not make you want to come home. So I made you want to kill me."` },
    { speaker: 'ain', text: `"No." Ain's light flared. "No. I chose. I hired him. I escaped."` },
    { speaker: 'voice_of_set', text: `"You escaped through a door I left open. Ashkarran had to fight you; my priests had to chase you. A door left open must look shut. I let you remember just enough to hate me, and I waited for you to come here and strike. You came wary instead." The serpent's head swung slowly toward Kord. "So."` },
    { text: `The serpent came off the obelisk faster than any eye could follow. Bronze coils whipped round Kord before his sword was half drawn, and lifted him off his feet, and closed. Steel bent. Bones creaked. Kord's roar of fury choked off into a terrible silence.`, sfx: 'serpent-hiss', effects: [{ fx: 'shake' }] },
    { text: `Toktai's arrows skated off the bronze like hail off a roof. Valka hacked at the coils until her sabre sang and her arms shook, and the serpent did not even turn its head. Kord's face was going dark.` },
    { speaker: 'voice_of_set', text: `"You cannot compel the Arbiter. But the Arbiter can choose."` },
    { text: `Ain did not hesitate. Not for the space of a single heartbeat. It flew straight at the obelisk, a streak of teal fire, and plunged into the black stone as into deep water, reaching down, down, through the hand and into the mind beneath, of its own will, with everything it was.` },
    { speaker: 'ain', text: `"*Let him go!*"`, effects: [{ fx: 'flash' }] },
    { text: `Somewhere far below, a key turned.` },
    { text: `The coils opened. Kord fell to the dust, gasping, on his knees. And the teal spark that was Ain was drawn down into the black heart of the obelisk, slowly, like a coin sinking in a well, and could not come out.`, effects: [{ leave: 'ain' }] },
    { speaker: 'voice_of_set', text: `"I never needed to force you, Arbiter. Only to give you something to reach for."` },
    { speaker: 'ain', text: `Faint, from very far inside the stone, and not afraid: "Kord. I knew. I did it anyway."` },
    { text: `Then the Stillness began.`, sfx: 'loop-stillness' },
    { text: `It came up out of the floor like cold water, and went through the chamber, and up through the stone, and out over Khemi. Valka froze with her sabre raised and her mouth open on a curse. Toktai froze with an arrow on the string. Thulamon's guards froze mid-breath, eyes open, and one of them was smiling. Far above, the roar of the revolt stopped all at once, like a song cut off in the middle of a word.`,
      effects: [{ freeze: 'toktai' }, { freeze: 'valka' }, { music: 'dungeon' }] },
    { text: `In all that chamber, in all that city, only two things moved. One was Thulamon, smiling. The other was Kord of Cimmeria, on his knees in the dust. He put one hand flat on the floor. Then he got up.` },
    { text: `Thulamon looked at him then, for the first time, with something in his face that might have been fear. It passed. The calm came back, smooth and warm as oil.` },
    { speaker: 'thulamon', text: `"So. You alone. How very strange." He spread his hands. "Kneel, or stand still forever. It is all one."` },
    { speaker: 'kord', text: `"I've never knelt. That was falling."` },
    { text: `The floor groaned. Stone slid over stone, sealing the way they had come, and Thulamon rose on a column of black stone toward the apex of the pyramid, still smiling, until the dark of the vault took him. Kord stood alone in the Heart of the Black Pyramid, among statues that had been his friends, and looked up.`,
      art: null, effects: [{ set: 'ch4.twist_done' }, { objective: { id: 'ch4_heart', to: 'done' } }] },
  ],
};

