export const objectives = [
  { id: 'ch4_heart', text: 'Reach the heart of the Black Pyramid before the dark of the moon.', done: F('ch4.twist_done'), members: ALL4,
    hints: ['The ritual is in the Black Pyramid of Khemi, two nights hence. First, Khemi itself.',
      'Khemi\'s slaves know the ways under the pyramid. The pens hold one who has dug there for three years.',
      'Free Bakari in the slave pens; he will lead you through the necropolis to the deep door. Then down, through the Hall of Judgement.'],
    party: {
      kord: `"The rower sits under the pyramid. We go in and kill him."`,
      toktai: `"A long road is short if you walk it angry. Kord will walk it very short."`,
      ain: `"It is under the pyramid, waiting. I can feel it the way you feel a cliff edge in the dark. I would like you to be the one who goes near it, Kord. Not me."`,
      valka: `"Two nights to the dark of the moon. Plenty of time to rob a god. I've done it in one."` } },
  { id: 'ch4_into_khemi', text: 'Get through the gate of Khemi.', done: F('ch4.gate_passed'), members: ALL4,
    hints: [`"Khemi lets in two kinds of foreigner: slaves and corpses." The slavers on the road east of the beach will have papers.`,
      'The slavers carry a writ with the seal of the slave market, and shackles. Valka has an idea.',
      `Give the slaver's writ to the gate captain (with the shackles in the bag), and when he asks Kord who his master is, answer "...Yes. Master."`],
    party: {
      kord: `"Valka has a plan. I can see it in her teeth. I am going to hate it."`,
      toktai: `"Slaves go in. Slavers go in. We have a slaver's papers and a slaver's chains. Wear the wolf's coat, walk among the wolves."`,
      ain: `"The writ bears the seal of the slave market. Statistically..." Kord looks at it. "...If we look like slaves, they will let us in."`,
      valka: `"Writ for me, shackles for you two, and a pretty jewel down my coat. When the captain asks, Kord, you say it nicely. You know what I mean."` } },
  { id: 'ch4_keys', text: 'Get Uzzah\'s keys back out of Old Nebet.', done: F('ch4.keys_found'), members: ALL4,
    hints: ['Old Nebet swallowed the keys and will eat nothing more. Something to purge her might help. Ask in the Temple Bazaar.',
      'The herbalist\'s purging root works, but Nebet won\'t eat medicine on its own. Shepherds hide it in a fig; Nebet eats meat. There are rats by the street drain, and Toktai has quick hands.',
      'Buy purging root from the herbalist, have Toktai catch a rat at the drain, combine the root with the rat, and give the stuffed rat to Old Nebet.'],
    party: {
      kord: `"A snake ate the keys. Make the snake give them back. I would hit it, but the whole street would hit me."`,
      toktai: `"He will not eat medicine. He would eat medicine dressed as dinner." Valka: "*She*." "She, then."`,
      ain: `"Old Nebet will not take the root alone. She would have to want it. Most creatures can be made to want almost anything, if it is wrapped properly." It sounds, for a moment, uneasy.`,
      valka: `"The old woman in the bazaar sells everything for everyone. Ask her what makes a fat thing give back its dinner."` } },
  { id: 'ch4_bakari', text: 'Free the singing Kushite in the slave pens.', done: F('ch4.bakari_freed'), members: ALL4,
    hints: ['The pens are locked, and the keys are inside a python.',
      'Once Old Nebet gives up Uzzah\'s keys, go down into the pens.',
      'Use the key ring on Bakari at the whipping post, and fight beside him when Uzzah calls his guards.'],
    party: {
      kord: `"The big one at the post. A man who laughs in chains is a man worth unchaining."`,
      toktai: `"Three years under the pyramid, the fat one said. Who knows the way through a hill? Ask the mole."`,
      ain: `"Bakari has dug under the pyramid for three years. He will know a way in that is not a door with guards on it."`,
      valka: `"I don't care if he knows the way to the moon. That man is coming out of those chains, and Uzzah is going to watch it happen."` } },
  { id: 'ch4_catacombs', text: 'Follow Bakari through the catacombs to the deep door.', done: F('ch4.bakari_left'), members: ALL4,
    hints: ['The necropolis gate lies south of the Street of Serpents. Bakari knows the way.',
      'The dead do not lie still down here. Fight your way to the deep door; the painted wall is worth a look on the way.',
      'Defeat the temple python lying across the deep door, then take the deep door down.'],
    party: {
      kord: `"Dead men walking. Hit them till they lie down again."`,
      toktai: `"The painted wall. A priest weighing a dead man who has no heart. When the walls talk, listen. Here they never shut up."`,
      ain: `"The mural shows a heartless mummy on a scale, lighter than a feather. It passed. I find I keep looking at it."`,
      valka: `"Snake on the door. Big one. My favourite kind of lock: the kind you can stab."` } },
  { id: 'sq3_jackal', side: true, text: 'Win the Jackal\'s wager.', lock: 'Must be done before you pass the Hall of Judgement.', done: F('ch4.jk_done'), members: ALL4,
    hints: ['The Jackal bets Toktai cannot take the cobra idol\'s jade eye without the guard ever knowing. A missing eye would be noticed. A guard who is looking elsewhere notices nothing.',
      'Toktai can carve an eye that will pass for jade in candlelight, if he has the wax for it, and the Jackal sells green candles. As for the guard: who in this party is best at being looked at?',
      'Buy a green candle from the Jackal, use it on Toktai to carve a wax eye, then use Valka on the guard. Bring the jade eye back to the Jackal, or keep it and sell it.'],
    party: {
      kord: '"Toktai wants that green eye. Toktai has the look of a man who will not sleep until he has it."',
      toktai: '"I need a fake eye, green as a pond, and a guard who is looking at anything but me. I can make the first. The second is not my talent."',
      ain: '"Do not ask me to glow, Kord. Not here. Ask Valka. Valka glows in a different way."',
      valka: '"A guard who loves an idol? Darling, I\'ve stolen captains from their own ships. Point me at him when Toktai\'s ready."',
    } },
  { id: 'ch4_judgement', text: 'Pass the Hall of Judgement.', done: F('ch4.guardian_dead'), members: ALL4,
    hints: [`"Only one whose heart is lighter than a feather may pass." Who among you has no heart?`,
      'Remember the catacomb mural: the heartless mummy passed. And remember what Ain told Valka on the Shrike.',
      'Use Ain on the scale. Then face the Guardian of Scales.'],
    party: {
      kord: `"Too heavy, the scale says. It has never weighed a Cimmerian before. It should have asked."`,
      toktai: `"The painted mummy passed because it had no heart. Who here has no heart? Besides Valka." Valka: "I heard that."`,
      ain: `"I have no heart, in the anatomical sense. I told Valka that on the Shrike. I have just remembered that I said it, and I wish I had not."`,
      valka: `"I heard what Toktai said. He's right, mind. But not about me."` } },
];

